'use strict';
let DATA,view='overview',lastMatrix=[];
const $=id=>document.getElementById(id),fmt=new Intl.NumberFormat('es-EC',{maximumFractionDigits:0}),dec=new Intl.NumberFormat('es-EC',{maximumFractionDigits:1});
const n=x=>x==null?'—':fmt.format(x),pct=x=>x==null?'—':dec.format(x*100)+'%',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const d=s=>Date.parse(s+'T00:00:00Z')/86400000,iso=x=>new Date(x*86400000).toISOString().slice(0,10),sum=rs=>rs.reduce((a,r)=>a+r.count,0),ratio=(a,b)=>b?a/b:null;
const defaults={start25:'2025-05-01',end25:'2025-09-30',start26:'2026-05-01',end26:'2026-09-30',cutoff:'2026-09-15'};
function state(){let s={};for(const k of ['scope','sede','career','modality','formal',...Object.keys(defaults)])s[k]=$(k).value;return s;}
function isTargetCareer(c){return DATA.targets.some(t=>t.career===c);}
function subset(s){return DATA.records.filter(r=>(s.scope!=='target'||isTargetCareer(r.career))&&(s.scope!=='uncovered'||!isTargetCareer(r.career))&&(!s.sede||r.sede===s.sede)&&(!s.career||r.career===s.career)&&(!s.modality||r.modality===s.modality)&&(s.formal!=='yes'||r.formal));}
function target(s){
 if(s.scope==='uncovered'||(s.scope==='all'&&!s.career))return null;
 if(s.sede)return DATA.targetDetails.filter(t=>t.sede===s.sede&&(!s.career||t.career===s.career)&&(!s.modality||mapMod(t.modality)===s.modality)).reduce((a,t)=>a+t.target,0);
 if(s.modality)return null;
 return DATA.targets.filter(t=>!s.career||t.career===s.career).reduce((a,t)=>a+t.target,0);
}
function mapMod(m){if(!m)return '';if(m.startsWith('PRESENCIAL'))return 'PRESENCIAL';if(m.startsWith('HIBR'))return 'HIBRIDA';return m;}
function metrics(s){
 const rows=subset(s),start=d(s.start26),end=d(s.end26),cut=d(s.cutoff),a=d(s.start25),b=d(s.end25),elapsed=Math.max(0,Math.min(cut,end)-start+1),duration=end-start+1,oldcut=Math.min(b,a+elapsed-1);
 const r26=rows.filter(r=>r.period==='B26'),r25=rows.filter(r=>r.period==='B25');
 const cur=r26.filter(r=>r.date&&d(r.date)>=start&&d(r.date)<=Math.min(end,cut)),prev=r25.filter(r=>r.date&&d(r.date)>=a&&d(r.date)<=oldcut),old=r25.filter(r=>r.date&&d(r.date)>=a&&d(r.date)<=b);
 const real=sum(cur),ytd=sum(prev),final=sum(old),meta=target(s),expected=meta==null?null:meta*elapsed/duration,projection=elapsed?real/elapsed*duration:null;
 return {rows,r26,r25,cur,prev,old,real,ytd,final,meta,expected,projection,elapsed,duration,oldcut,daysLeft:Math.max(end-cut,0),gap:meta==null?null:meta-real,progress:ratio(real,meta),delta:ytd?real/ytd-1:null,required:cut<end&&meta!=null?Math.max(meta-real,0)/(end-cut):null,out26:sum(r26.filter(r=>r.date&&(d(r.date)<start||d(r.date)>end))),out25:sum(r25.filter(r=>r.date&&(d(r.date)<a||d(r.date)>b))),formal:sum(cur.filter(r=>r.formal))};
}
function kpi(label,value,hint,primary=false){return `<article class="kpi ${primary?'primary':''}"><div class="label">${label}</div><strong>${value}</strong><div class="hint">${hint}</div></article>`;}
function panel(title,sub,body,tag=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${sub}</p></div>${tag?`<span class="pill">${tag}</span>`:''}</div>${body}</section>`;}
function trend(s,m,projection=false){
 const w=820,h=260,left=52,top=15,bottom=35,points=Math.max(m.duration,d(s.end25)-d(s.start25)+1),horizon=projection?m.duration:m.elapsed;
 if(!m.elapsed)return '<p class="empty">El corte es anterior al inicio del período.</p>';
 const arr=(rows,start)=>{const counts=new Map();rows.forEach(r=>{let i=d(r.date)-d(start);counts.set(i,(counts.get(i)||0)+r.count)});let acc=0;return Array.from({length:points},(_,i)=>acc+=counts.get(i)||0)};
 const cur=arr(m.cur,s.start26),prev=arr(m.old,s.start25),max=Math.max(m.real,m.final,m.meta||0,projection?m.projection||0:0,1)*1.08;
 const x=i=>left+(w-left-15)*i/Math.max(points-1,1),y=v=>h-bottom-(h-top-bottom)*v/max;
 const path=(v,len)=>v.slice(0,len).map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+','+y(v).toFixed(1)).join(' ');
 let grid=Array.from({length:5},(_,i)=>{let v=max*i/4;return `<line x1="${left}" x2="${w-15}" y1="${y(v)}" y2="${y(v)}" stroke="#e8ebf2"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${n(v)}</text>`}).join('');
 let predicted=projection&&m.projection!=null?`<path d="M${x(m.elapsed-1)},${y(m.real)} L${x(m.duration-1)},${y(m.projection)}" stroke="#e97926" stroke-width="3" stroke-dasharray="7 5" fill="none"/>`:'';
 let meta=m.meta?`<line x1="${left}" x2="${x(m.duration-1)}" y1="${y(m.meta)}" y2="${y(m.meta)}" stroke="#a5adbf" stroke-dasharray="4 5"/><text x="${w-15}" y="${y(m.meta)-7}" text-anchor="end">Meta ${n(m.meta)}</text>`:'';
 return `<svg class="chart" role="img" aria-label="Matrículas acumuladas por día de período B25 y B26" viewBox="0 0 ${w} ${h}">${grid}${meta}<path d="${path(prev,Math.min(m.elapsed,points))}" fill="none" stroke="#a6a9bc" stroke-width="3"/><path d="${path(cur,m.elapsed)}" fill="none" stroke="#654087" stroke-width="3.5"/>${predicted}${[0,.25,.5,.75,1].map(f=>`<text x="${x(Math.floor((points-1)*f))}" y="${h-6}" text-anchor="middle">Día ${Math.floor((points-1)*f)+1}</text>`).join('')}</svg><div class="legend"><span><b style="background:#654087"></b>B26 real</span><span><b style="background:#a6a9bc"></b>B25 equivalente</span>${projection?'<span><b style="background:#e97926"></b>Proyección lineal</span>':''}</div>`;
}
function overview(s,m){
 let sedes=['MATRIZ','QUITO','LATACUNGA'].filter(sede=>!s.sede||s.sede===sede).map(sede=>({sede,m:metrics({...s,sede})}));
 let bars=sedes.map(({sede,m:mm})=>`<div class="barrow"><div class="barlabel"><span>${sede==='MATRIZ'?'Matriz · Ambato':sede}</span><strong>${n(mm.real)}</strong></div><div class="bartrack"><div class="barfill" style="width:${100*mm.real/Math.max(...sedes.map(x=>x.m.real),1)}%"></div></div><div class="hint" style="margin-top:6px">B25 equivalente: ${n(mm.ytd)} · Meta explícita: ${n(mm.meta)}</div></div>`).join('');
 return `<div class="kpis">${kpi('Matrículas B26 al corte',n(m.real),`${n(m.formal)} formalizadas · ${n(m.real-m.formal)} sin formalizar`,true)}${kpi('Meta del período',n(m.meta),s.sede?'Solo asignaciones explícitas del Excel':'Metas por carrera ajustadas a 2.400')}${kpi('Avance sobre meta',pct(m.progress),`Brecha: ${n(m.gap)} matrículas`)}${kpi('Variación vs B25 YTD',pct(m.delta),`B25 al día equivalente: ${n(m.ytd)}`)}</div><div class="grid">${panel('Evolución de la matrícula',`Día ${m.elapsed} de ${m.duration} · Corte B25 equivalente: ${iso(m.oldcut)}`,trend(s,m),'Acumulado')}${panel('Contribución por sede','Matrículas dentro del período y hasta el corte.',bars)}</div><div class="kpis" style="margin-top:20px">${kpi('Objetivo lineal al corte',n(m.expected),`${pct(m.expected?m.real/m.expected:null)} de cumplimiento al corte`)}${kpi('Proyección de cierre',n(m.projection),'Ritmo diario × duración del período')}${kpi('Ritmo necesario / día',m.required==null?'—':dec.format(m.required),`${n(m.daysLeft)} días restantes`)}${kpi('B25 total en período',n(m.final),'Solo mayo a septiembre')}</div>${warnings(s,m)}`;
}
function warnings(s,m){return `<div class="note">${s.scope!=='target'?'Este universo no se compara con la meta institucional: los indicadores de meta se muestran vacíos. ':''}${s.modality&&!s.sede?'No hay metas completas por modalidad: se omiten los indicadores que dependen de esa meta. ':''}Fuera del período configurado: B26 <b>${n(m.out26)}</b> y B25 <b>${n(m.out25)}</b>. Se excluyen del comparativo. La formalización sigue siendo una regla candidata; puedes consultar ambos escenarios. Las metas de sede suman solo asignaciones identificables y no deben sumarse como sustituto de la meta institucional.</div>`;}
function matrix(s,m){
 const careers=[...new Set([...DATA.targets.map(t=>t.career),...m.rows.map(r=>r.career)])].filter(c=>!s.career||s.career===c).sort();
 lastMatrix=careers.map(c=>({career:c,...metrics({...s,career:c})}));
 const cells=r=>`<td>${n(r.final)}</td><td>${n(r.ytd)}</td><td>${n(r.meta)}</td><td>${n(r.expected)}</td><td>${n(r.real)}</td><td class="${r.meta!=null&&r.real-r.expected<0?'negative':'positive'}">${r.meta==null?'—':n(r.real-r.expected)}</td><td>${pct(r.progress)}</td><td>${pct(r.ytd?r.real/r.ytd:null)}</td><td>${n(r.projection)}</td>`;
 let rows=lastMatrix.map(r=>`<tr><td>${esc(r.career)}</td>${cells(r)}</tr>`).join('');
 return panel('Cuadro de avance por carrera','YTD al mismo día de período · real vs objetivo lineal · proyección de cierre',`<button class="export" id="export" style="margin-bottom:15px">Exportar cuadro CSV</button><div class="tablewrap"><table><thead><tr><th>Carrera</th><th>B25 final</th><th>B25 YTD</th><th>Meta B26</th><th>Objetivo al corte</th><th>B26 real</th><th>Δ vs objetivo</th><th>Avance meta</th><th>Real / B25 YTD</th><th>Proyección</th></tr></thead><tbody><tr class="total"><td>TOTAL DEL FILTRO</td>${cells(m)}</tr>${rows}</tbody></table></div>`)+warnings(s,m);
}
function forecast(s,m){
 return `<div class="kpis">${kpi('Proyección lineal',n(m.projection),'Escenario basado en el promedio desde mayo',true)}${kpi('Objetivo al corte',n(m.expected),`Real: ${n(m.real)} · Cumplimiento: ${pct(ratio(m.real,m.expected))}`)}${kpi('Promedio diario',m.elapsed?dec.format(m.real/m.elapsed):'—','Incluye días sin matrículas')}${kpi('Días para el cierre',n(m.daysLeft),`Fecha de cierre: ${s.end26}`)}</div>${panel('Ritmo observado y escenario de cierre','La línea discontinua mantiene el promedio diario. No es una garantía ni una estimación probabilística.',trend(s,m,true),'Escenario lineal')}${panel('Cómo se calcula','Las fechas y filtros se aplican antes de calcular los indicadores.',`<table><tbody><tr><td>YTD B25 equivalente</td><td>Matrículas B25 hasta el día ${m.elapsed} de su período</td></tr><tr><td>Objetivo al corte</td><td>Meta × ${m.elapsed} / ${m.duration}</td></tr><tr><td>Proyección lineal</td><td>${n(m.real)} / ${m.elapsed} × ${m.duration} = ${n(m.projection)}</td></tr><tr><td>Velocidad necesaria</td><td>Máximo(meta − real, 0) / días restantes</td></tr></tbody></table>`)}${warnings(s,m)}`;
}
function quality(s,m){let q=DATA.qa;
 const items=[['Filas de 615.xlsx',q.rawB26,'B26: 1.929 · A26: 11 · B25: 2'],['Candidatos B26',q.candidateB26,'Antes de aplicar fechas o filtros del panel'],['B26 cubierto por metas',q.coveredCounts.B26,'Carreras incluidas en Metas.xlsx'],['B26 sin meta',q.uncoveredCounts.B26,'Se mantiene separado del avance institucional'],['Histórico B25',q.totalB25,'Hoja2 · antes de filtrar mayo–septiembre'],['Identificaciones duplicadas',q.duplicateIdentifiersB26,'En 615.xlsx completo. Se conservan los registros.'],['Metas carrera originales',q.originalTargets,'35 carreras; ajuste proporcional y restos mayores'],['Metas carrera ajustadas',q.adjustedTargets,'Suma exacta 2.400; factor inicial 0,96'],['Metas sin sede identificable',q.unassignedTargetRows,`De ${q.targetDetailRows} filas de detalle; no se distribuyen por suposición`],['Fechas fuera de período B26',m.out26,'En la selección actual'],['Fechas fuera de período B25',m.out25,'En la selección actual']];
 return `<div class="quality">${items.map(([a,b,c])=>`<article class="item"><span>${a}</span><strong>${n(b)}</strong><div class="hint">${c}</div></article>`).join('')}</div>${panel('Alcance y controles','Los originales se conservan; el panel usa agregados por fecha, carrera, sede, modalidad y formalización.',`<p>Regla candidata B26: período B26, HOMOLOGA = NO y MATRÍCULA EN PRIMERO = SI. La selección por formalización se aplica a ambos períodos. No se eliminaron duplicados automáticamente.</p><p>Las carreras se normalizan por acentos, espacios y prefijos de ingeniería. Las carreras sin equivalencia de meta permanecen separadas, con meta 0 cuando corresponde. El total candidato incluye programas de posgrado presentes en la fuente: la comparabilidad de esa población con la meta requiere conciliación.</p><p>Las metas de sede se mantienen sin el factor 0,96. Solo se asignan cuando el Excel identifica AMB, UIO o LTG. Modalidades sin sede, como EN LÍNEA, no se adjudican a una sede.</p><p>Los días sin registros cuentan en el ritmo diario. Los ceros en metas de sede significan ausencia de una asignación identificable; los guiones indican un cociente indefinido o una meta de modalidad que no se puede determinar.</p>`)}${panel('Carreras sin meta canónica','Revisar equivalencias y cobertura antes de considerar definitivos los indicadores de cumplimiento.',`<div class="tablewrap"><table><thead><tr><th>Carrera</th><th>B26 en selección</th><th>B25 en selección</th></tr></thead><tbody>${q.unmappedCareers.map(c=>{let a=metrics({...s,career:c});return `<tr><td>${esc(c)}</td><td>${n(a.real)}</td><td>${n(a.final)}</td></tr>`}).join('')}</tbody></table></div>`)}${panel('Fuentes de esta versión','Lectura real de los tres archivos proporcionados.',`<p>${DATA.sources.map(esc).join('<br>')}</p><p>Ventana observada B26: ${q.sourceDateRanges.B26.start} a ${q.sourceDateRanges.B26.end}.<br>Ventana observada B25: ${q.sourceDateRanges.B25.start} a ${q.sourceDateRanges.B25.end}.</p>`)}`;
}
function render(){if(!DATA)return;let s=state();let bad=Object.keys(defaults).some(k=>!s[k])||d(s.end25)<d(s.start25)||d(s.end26)<d(s.start26)||s.cutoff>DATA.snapshot;
 if(bad){$('error').textContent='Revisa las fechas: inicio debe preceder al cierre y el corte no puede superar el 15/09/2026, último día de la fuente.';$('content').innerHTML='';return;}
 $('error').textContent='';let m=metrics(s);$('content').innerHTML=({overview,matrix,forecast,quality}[view])(s,m);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('title').textContent={overview:'Resumen ejecutivo',matrix:'Cuadro comparativo',forecast:'Tendencia y proyección',quality:'Calidad y fuentes'}[view];if($('export'))$('export').onclick=exportCSV;return m;}
function exportCSV(){let headers=['Carrera','B25 final','B25 YTD','Meta B26','Objetivo al corte','B26 real','Avance meta','Proyeccion'];let csv=[headers,...lastMatrix.map(r=>[r.career,r.final,r.ytd,r.meta,r.expected,r.real,r.progress,r.projection])].map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');let url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='admisiones-cuadro.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function init(){try{let r=await fetch('data.json');if(!r.ok)throw Error('No se pudieron cargar los datos');DATA=await r.json();for(let [id,prop] of [['sede','sede'],['career','career'],['modality','modality']]){let vals=[...new Set(DATA.records.map(r=>r[prop]))];if(id==='career')vals=[...new Set([...vals,...DATA.targets.map(t=>t.career)])];vals.sort().forEach(v=>{let o=document.createElement('option');o.value=v;o.textContent=v;$(id).append(o)});}Object.entries(defaults).forEach(([k,v])=>$(k).value=v);document.querySelectorAll('select,input').forEach(e=>e.addEventListener('change',render));document.querySelectorAll('nav button').forEach(e=>e.onclick=()=>{view=e.dataset.view;render()});$('reset').onclick=()=>{$('scope').value='target';for(let k of ['sede','career','modality','formal'])$(k).value='';Object.entries(defaults).forEach(([k,v])=>$(k).value=v);render();};render();
 if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'consultar_admisiones',description:'Obtiene indicadores con los filtros visibles.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>{let m=metrics(state());return {real:m.real,ytdB25:m.ytd,meta:m.meta,proyeccion:m.projection};}});}catch(e){console.warn('WebMCP no disponible',e);}}
 }catch(e){$('error').textContent=e.message;$('content').innerHTML='<p class="empty">No fue posible cargar las fuentes. Recarga la página.</p>';}}
init();
